import abc

import six
from moler.cmd.commandtextualgeneric import CommandTextualGeneric


@six.add_metaclass(abc.ABCMeta)
class Genericbtssm(CommandTextualGeneric):
    """GenericBtssm command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Genericbtssm command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution.
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command.
        """
        super(Genericbtssm, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
